@startuml

class City {
  + Name : string
}

class H2SLocation {
  + LocationID : int
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class PickupRequest {
  + RequestID : int
  + ItemDescription : string
  + RequestedDate : date
  + RequestedTime : time
}

class Vehicle {
  + LicensePlate : string
  + StorageCapacity : float
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : string[]
}

class PickupRoute {
  + RouteID : int
  + Date : date
}

class ScheduledItem {
  + Dimensions : string
  + Weight : float
}

class DistributionCenter {
  + Address : string
}

class Article {
  + RFIDTag : string
  + Description : string
  + Category : string
}

class Category {
  + CategoryName : string
}

class Employee {
  + EmployeeID : int
  + Name : string
}

class Client {
  + Name : string
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
  + Address : string
}

City "1" -- "0..*" H2SLocation
H2SLocation "1" -- "0..*" DistributionCenter
H2SLocation "1" -- "0..*" FoodBank
Resident "1" -- "*" PickupRequest
PickupRequest "*" -- "1" Resident
PickupRequest "1" -- "1..*" ScheduledItem
Vehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
PickupRoute "1" -- "*" ScheduledItem
DistributionCenter "1" -- "*" Article
Article "*" -- "1" Category
Employee "1" -- "*" Article : examines
Client "*" -- "1" DistributionCenter : receivesFrom
Employee "1" -- "*" Client : calls
Employee "1" -- "*" Article : arrangesDelivery
VolunteerDriver "1" -- "*" Article : delivers
Resident "1" -- "*" Article : donates
DistributionCenter "1" -- "*" Article : stores
DistributionCenter "1" -- "*" FoodBank : distributesTo
@enduml

